import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'
import { IntegerColumn, StringColumn, BooleanColumn } from '@servicenow/sdk/core'

Flow(
    {
        $id: Now.ID['687a54cb829740f6bb2a9ddb7032f419'],
        name: 'Example_1_Daily Incident Processor_v3',
        description: `Triggers - Daily
Flow Variables
If 
IfElse
For Each 
Skip Iteration
Set Flow Variables
EndFlow
OOB Action: Look Up Records, Log`,
        flowVariables: {
            normalPriorityCount: IntegerColumn({
                label: 'normalPriorityCount',
                mandatory: true,
            }),
            totalProcessed: IntegerColumn({
                label: 'totalProcessed',
                mandatory: true,
            }),
            processingStatus: StringColumn({
                label: 'processingStatus',
                mandatory: true,
            }),
            highPriorityCount: IntegerColumn({
                label: 'highPriorityCount',
                mandatory: true,
            }),
            shouldContinue: BooleanColumn({
                label: 'shouldContinue',
                mandatory: true,
                default: true,
            }),
        },
    },
    wfa.trigger(
        trigger.scheduled.monthly,
        {
            $id: Now.ID['4f78bb6ca9367250f8776fbd849e7ba2'],
        },
        {
            day_of_month: 3,
            time: Time(
                {
                    hours: 23,
                },
                'UTC'
            ),
        }
    ),
    (_params) => {
        const actionInstance_1 = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['7db97f20a9767250f8776fbd849e7b59'],
                uuid: '5117f3c3-beb1-4866-971a-4f8003aa355a',
            },
            {
                table_name: 'incident',
                values: TemplateValue({
                    short_description: 'Process Started',
                    priority: '1',
                }),
            }
        )
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['68583b6ca9367250f8776fbd849e7b76'],
                annotation: 'Log flow execution start',
                uuid: '1edb09e1-8456-4a89-ad77-168b13fcbe6d',
            },
            {
                log_level: 'info',
                log_message: 'Monthly Incident Processor started. Querying unassigned incidents...',
            }
        )
        wfa.flowLogic.setFlowVariables(
            {
                annotation: 'Initialize processing counters and status',
                $id: Now.ID['5c583b6ca9367250f8776fbd849e7b58'],
            },
            _params.flowVariables,
            {
                totalProcessed: 0,
                highPriorityCount: 0,
                normalPriorityCount: 0,
                processingStatus: 'STARTED',
                shouldContinue: true,
            }
        )
        const actionInstance_4 = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['e4583b6ca9367250f8776fbd849e7b78'],
                annotation: 'Query all unassigned incidents',
                uuid: 'f3118178-31d2-456d-8dc8-7a00ae5ec749',
            },
            {
                conditions:
                    'assignment_groupISEMPTY^active=true^NQsys_created_onONLast month@javascript:gs.beginningOfLastMonth()@javascript:gs.endOfLastMonth()^ORDERBYpriority',
                table: 'incident',
                sort_type: 'sort_desc',
                sort_column: 'sys_created_on',
                max_results: 1000,
            }
        )
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(actionInstance_4.Count, 'integer')}=0`,
                annotation: 'Check if there are incidents to process',
                $id: Now.ID['18583b6ca9367250f8776fbd849e7b5b'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['28583b6ca9367250f8776fbd849e7b79'],
                        uuid: '07e41fa4-5969-4644-9677-b96997252c9f',
                    },
                    {
                        log_level: 'info',
                        log_message: 'No unassigned incidents found in the last 24 hours.',
                    }
                )
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['f5f9b760a9767250f8776fbd849e7b65'],
                        uuid: '337006a0-0223-4d79-91aa-fe2ce41a021b',
                    },
                    {
                        record: wfa.dataPill(actionInstance_1.record, 'reference'),
                        table_name: 'incident',
                        values: TemplateValue({
                            description: 'No Un assigned incidents',
                        }),
                    }
                )
                wfa.flowLogic.endFlow({
                    annotation: 'End flow early - no incidents to process',
                    $id: Now.ID['94583b6ca9367250f8776fbd849e7b5d'],
                })
            }
        )
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['68583b6ca9367250f8776fbd849e7b7a'],
                uuid: '591118ec-ae9b-44d6-82ac-472dca1a5d5c',
            },
            {
                log_level: 'info',
                log_message: `Found ${wfa.dataPill(actionInstance_4.Count, 'integer')} unassigned incidents. Beginning processing...`,
            }
        )
        wfa.flowLogic.forEach(
            wfa.dataPill(actionInstance_4.Records, 'records'),
            {
                annotation: 'Process each unassigned incident',
                $id: Now.ID['98583b6ca9367250f8776fbd849e7b5e'],
            },
            (item_10) => {
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(item_10.priority, 'choice')}=1`,
                        annotation: 'Handle Priority 1 - Critical incidents',
                        $id: Now.ID['ec583b6ca9367250f8776fbd849e7b6c'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['a8583b6ca9367250f8776fbd849e7b7b'],
                                uuid: 'd2829217-fc64-4abd-bfc4-482656ea18a1',
                            },
                            {
                                log_level: 'error',
                                log_message: `CRITICAL: Incident  ${wfa.dataPill(item_10.assignment_group, 'reference')}${wfa.dataPill(item_10, 'reference')}${wfa.dataPill(item_10.rfc.category, 'choice')}
requires immediate attention!`,
                            }
                        )
                        wfa.action(
                            action.core.updateRecord,
                            {
                                $id: Now.ID['453aff60a9767250f8776fbd849e7b0c'],
                                uuid: '28fdc2b8-df77-40f9-b392-1799d96a13b5',
                            },
                            {
                                record: wfa.dataPill(actionInstance_1.record, 'reference'),
                                table_name: 'incident',
                                values: TemplateValue({
                                    description: 'P1 is created',
                                }),
                            }
                        )
                    }
                )
                wfa.flowLogic.elseIf(
                    {
                        condition: `${wfa.dataPill(item_10.priority, 'choice')}=2`,
                        annotation: 'Handle Priority 2 - High priority incidents',
                        $id: Now.ID['e0583b6ca9367250f8776fbd849e7b6e'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['e8583b6ca9367250f8776fbd849e7b7c'],
                                uuid: '4b2d862b-4dcb-481e-a156-49dddf0c9004',
                            },
                            {
                                log_level: 'warn',
                                log_message: `HIGH PRIORITY: Incident  - ${wfa.dataPill(item_10.assignment_group, 'reference')}${wfa.dataPill(item_10.rfc.category, 'choice')}`,
                            }
                        )
                        wfa.action(
                            action.core.updateRecord,
                            {
                                $id: Now.ID['cb4ab3a0a9767250f8776fbd849e7bb3'],
                                uuid: 'd29173f2-d992-45ec-b677-3a9f6c9e602a',
                            },
                            {
                                record: wfa.dataPill(actionInstance_1.record, 'reference'),
                                table_name: 'incident',
                                values: TemplateValue({
                                    description: 'P2 is created',
                                }),
                            }
                        )
                    }
                )
                wfa.flowLogic.elseIf(
                    {
                        condition: `${wfa.dataPill(item_10.priority, 'choice')}=3`,
                        annotation: 'Handle Priority 3 - Moderate priority',
                        $id: Now.ID['a0583b6ca9367250f8776fbd849e7b70'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['2c583b6ca9367250f8776fbd849e7b7d'],
                                uuid: '816bb8df-deae-4561-a924-5c58dae6d98b',
                            },
                            {
                                log_level: 'info',
                                log_message: `Moderate priority incident ${wfa.dataPill(item_10.sys_class_name, 'choice')} identified`,
                            }
                        )
                        wfa.action(
                            action.core.updateRecord,
                            {
                                $id: Now.ID['9c7a3ba0a9767250f8776fbd849e7b6d'],
                                uuid: 'bdb274a7-0c5e-4897-b502-487024536391',
                            },
                            {
                                record: wfa.dataPill(actionInstance_1.record, 'reference'),
                                table_name: 'incident',
                                values: TemplateValue({
                                    description: 'P3 created',
                                }),
                            }
                        )
                    }
                )
                wfa.flowLogic.elseIf(
                    {
                        condition: `${wfa.dataPill(item_10.priority, 'choice')}=4^NQ${wfa.dataPill(item_10.priority, 'choice')}=5`,
                        annotation: 'Else if the Priority is Low or Planning',
                        $id: Now.ID['a4583b6ca9367250f8776fbd849e7b71'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['6c583b6ca9367250f8776fbd849e7b7e'],
                                uuid: '1e295392-ce77-4d65-8a91-70520406cd9f',
                            },
                            {
                                log_level: 'info',
                                log_message: `Moderate priority incident ${wfa.dataPill(item_10.sys_class_name, 'choice')} identified`,
                            }
                        )
                        wfa.action(
                            action.core.updateRecord,
                            {
                                $id: Now.ID['d49a7fa0a9767250f8776fbd849e7b47'],
                                uuid: '1865b622-4f07-4e17-b34f-d1b030a7a21e',
                            },
                            {
                                record: wfa.dataPill(actionInstance_1.record, 'reference'),
                                table_name: 'incident',
                                values: TemplateValue({
                                    description: 'P4 or P5 created',
                                }),
                            }
                        )
                    }
                )
                wfa.flowLogic.else(
                    {
                        annotation: 'else',
                        $id: Now.ID['a8583b6ca9367250f8776fbd849e7b72'],
                    },
                    () => {
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['ac583b6ca9367250f8776fbd849e7b7f'],
                                uuid: '5f22edca-d2cd-4752-b496-6a9e17419d3a',
                            },
                            {
                                log_level: 'info',
                                log_message: 'Exiting loop if priority is not set',
                            }
                        )
                        wfa.flowLogic.exitLoop({
                            annotation: 'exit loop',
                            $id: Now.ID['ac583b6ca9367250f8776fbd849e7b73'],
                        })
                    }
                )
            }
        )
        wfa.flowLogic.setFlowVariables(
            {
                annotation: 'Set processing complete status',
                $id: Now.ID['a0583b6ca9367250f8776fbd849e7b75'],
            },
            _params.flowVariables,
            {
                processingStatus: 'COMPLETED',
                shouldContinue: false,
            }
        )
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['ec583b6ca9367250f8776fbd849e7b80'],
                annotation: 'Log comprehensive execution summary',
                uuid: '77ddc9bb-eb8c-4cce-b3d2-28c9428b115b',
            },
            {
                log_level: 'info',
                log_message: `
=== DAILY INCIDENT PROCESSOR SUMMARY ===
Status: ${wfa.dataPill(_params.flowVariables.processingStatus, 'string')}
Total Incidents Processed: ${wfa.dataPill(_params.flowVariables.totalProcessed, 'integer')}
High Priority (P1/P2): ${wfa.dataPill(_params.flowVariables.highPriorityCount, 'integer')}
Normal/Low Priority (P3/P4): ${wfa.dataPill(_params.flowVariables.normalPriorityCount, 'integer')}
Processing Complete: ${wfa.dataPill(_params.flowVariables.shouldContinue, 'boolean')}
=========================================
                `,
            }
        )
    }
)
